    public Agent addToCustomers( UUID parentId, Customer addTo ) {
	    LOGGER.info("handling AssignCustomersToAgentEvent - " );
	    
	    Agent parentEntity = repository.findById(parentId).get();
	    Customer child = registry.project( Customer.class, addTo.getCustomerId());
	    
	    parentEntity.getCustomers().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Customers
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Agent
     */
	public Agent removeFromCustomers( UUID parentId, Customer removeFrom ) {
	    LOGGER.info("handling RemoveCustomersFromAgentEvent " );
	
	    Agent parentEntity = repository.findById(parentId).get();
	    Customer child = registry.project( Customer.class, removeFrom.getCustomerId());
	    
	    parentEntity.getCustomers().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



